# Completa la línea marcada y compruébala con py check.
def mas_raros(distancias, n):
    # distancias: {id: distancia al centro}
    orden = sorted(distancias, key=lambda c: distancias[c])   # ← cambia esta línea: de mayor a menor
    return orden[:n]

print(mas_raros({"cli-001": 0.1, "cli-039": 0.98, "cli-041": 0.2}, 1))   # ['cli-039']
